#include <iostream>
#include <vector>
template <typename T>
void myTemplateFunction(T value) {
  std::cout << "Value: " << value << std::endl;
}
extern template void myTemplateFunction<int>(int);
extern template void myTemplateFunction<double>(double);
int main() {
  myTemplateFunction<int>(10);
  myTemplateFunction<double>(3.14);
  return 0;
}
